import {expect, it, jest} from '@jest/globals';
import {createChatOrchestrator} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

// specs/hal-engine-config-hooks/spec.md#7
it('passes a beforeSession error and the same session to onError', async () => {
  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
  const error = new Error('beforeSession failed');
  const onError = jest.fn(async (_session: ChatSession, _error: Error) => {});
  const provider: AIProvider = {
    async *sendMessage() {},
    async generateStructured<T>() { return {} as T; },
  };
  const promptBuilder = new PromptBuilder({baseSystemPrompt: 'HAL'});
  const orchestrator = createChatOrchestrator(provider, promptBuilder, undefined, {
    hooks: {beforeSession: async () => { throw error; }, onError},
  });

  await expect(orchestrator.processMessage(session)).rejects.toBe(error);
  expect(onError).toHaveBeenCalledWith(session, error);
});
EOF
 timeout 300 npm test -- --runInBand --runTestsByPath src/orchestration/chatOrchestrator.beforeSession.test.ts"
